{{# popups }}
<div class="layerpop noti style02 window hide" id="popup_{{{ id }}}" style="width: {{{ popupwidth }}}px; height: {{{ popupheight }}}px; left: {{{ popupx }}}px; top: {{{ popupy }}}px;">
    <h3 class="pop-title">
        {{{ title }}}
        <a href="#none" class="close close_{{{ id }}}">close</a>
    </h3>
    <div class="pop-contents" style="{{# availablescroll }}overflow: auto;{{/ availablescroll }}">
        {{{ description }}}
    </div>
    <div class="pop-footer">
        <input type="button" class="btns blue close_{{{ id }}}" value="닫기">
    </div>
    <div class="ft" ><label><input type="checkbox" id="todaycloseyn_{{{ id }}}"> 오늘하루 열지않기</label>
</div>
{{/ popups }}

<script>
$(document).ready(function () {
    getCookieMobile();
    {{# popups }}
    $(".close_{{{ id }}}").click(function () {
        if($("#todaycloseyn_{{{ id }}}").prop("checked")){
            setCookieMobile( "todayCookie_{{{ id }}}", "done" , 1);
        }

        $("#popup_{{{ id }}}").html('');
    });
    {{/ popups }}
});
 
function setCookieMobile ( name, value, expiredays ) {
    var todayDate = new Date();
    todayDate.setDate( todayDate.getDate() + expiredays );
    document.cookie = name + "=" + escape( value ) + "; path=/; expires=" + todayDate.toGMTString() + ";"
}

function getCookieMobile () {
    var cookiedata = document.cookie;

    {{# popups }}
    if ( cookiedata.indexOf("todayCookie_{{{ id }}}=done") < 0 ){
         $("#popup_{{{ id }}}").show();
    }
    else {
        $("#popup_{{{ id }}}").hide();
    }
    {{/ popups }}
}

</script>
